const topUps: GuideDepthRecord = {
  'vine-to-glass': {
    en: ['Every transfer leaves a measurable clue: juice turbidity, extraction colour, fermentation density, acid profile, dissolved oxygen or the grain of tannin. A host can follow one lot through these checkpoints and connect an operation to a glass observation without pretending the link is exclusive. The same sensory result may have more than one cause, so the best conclusion names the evidence and the remaining uncertainty.'],
    de: ['Jeder Übergang hinterlässt ein prüfbares Zeichen: Trübung des Mosts, Extraktionsfarbe, Gärdichte, Säureprofil, gelöster Sauerstoff oder Tanninkorn. Ein Host kann eine Partie durch diese Kontrollpunkte verfolgen und Kellerarbeit mit Glasbeobachtung verbinden, ohne eine einzige Ursache vorzutäuschen. Dasselbe Ergebnis kann mehrere Gründe haben; eine gute Schlussfolgerung nennt Beleg und verbleibende Unsicherheit.'],
    fr: ['Chaque transfert laisse un indice mesurable : turbidité du jus, couleur d’extraction, densité fermentaire, profil acide, oxygène dissous ou grain tannique. Un hôte peut suivre un lot à ces étapes et relier geste de cave et observation sans prétendre à une cause unique. Une même sensation peut avoir plusieurs origines ; une conclusion solide nomme la preuve et l’incertitude restante.'],
    es: ['Cada transferencia deja una pista medible: turbidez del mosto, color de extracción, densidad de fermentación, perfil ácido, oxígeno disuelto o grano del tanino. Un anfitrión puede seguir un lote en esos controles y relacionar bodega y copa sin fingir una causa única. La misma sensación puede tener varios orígenes; una conclusión sólida nombra la evidencia y la incertidumbre que queda.'],
  },
  'taste-with-intention': {
    en: ['The discipline is valuable because preference is allowed to remain personal. Two tasters may agree that a wine is high in acid and disagree about whether that makes it refreshing. Record both statements separately. A note becomes useful when it predicts an action—another serving temperature, a dish, a decanting interval or a different style to compare. Over time, these small predictions teach which perceptions are stable for you and which depend on fatigue, expectation, food or glass.', 'A deliberate tasting can also include a revisit after food. Salt, fat and protein alter the impression of acidity, tannin and alcohol, so write the wine alone before taking a bite. Return to the same structure questions afterward: what softened, what became sharper and what aroma bridged the dish? This keeps pairing evidence connected to the original observation.'],
    de: ['Die Methode ist wertvoll, weil Vorliebe persönlich bleiben darf. Zwei Verkoster können sich auf hohe Säure einigen und dennoch verschieden beurteilen, ob sie erfrischt. Notiere beide Aussagen getrennt. Eine Notiz wird nützlich, wenn sie eine Handlung vorhersagt: andere Temperatur, ein Gericht, eine Dekantierzeit oder ein Vergleichsstil. Mit der Zeit zeigen kleine Vorhersagen, welche Eindrücke stabil sind und welche von Müdigkeit, Erwartung, Essen oder Glas abhängen.', 'Eine bewusste Verkostung kann nach einem Bissen wiederholt werden. Salz, Fett und Eiweiß verändern den Eindruck von Säure, Tannin und Alkohol; notiere den Wein daher zuerst allein. Kehre danach zu denselben Strukturfragen zurück: Was wurde weicher, was schärfer, und welches Aroma verband Wein und Gericht? So bleibt die Pairing-Beobachtung mit dem ursprünglichen Befund verbunden. Die Reihenfolge der Proben sollte ebenfalls gleich bleiben, damit Sättigung nicht wie ein Geschmacksunterschied wirkt.'],
    fr: ['La méthode compte parce que la préférence peut rester personnelle. Deux dégustateurs peuvent reconnaître une acidité élevée et diverger sur son effet rafraîchissant. Notez séparément les deux propositions. Une note devient utile lorsqu’elle prédit une action : autre température, plat, durée d’aération ou style à comparer. À force de petites prédictions, vous découvrez quelles perceptions restent stables et lesquelles dépendent fatigue, attente, nourriture ou verre.', 'Une dégustation intentionnelle peut être reprise après une bouchée. Sel, gras et protéines changent l’impression d’acidité, de tanin et d’alcool ; notez donc le vin seul. Revenez ensuite aux mêmes questions de structure : qu’est-ce qui s’est assoupli, accentué, et quel arôme relie le plat au vin ? L’accord reste ainsi une observation testable, non une impression séparée.'],
    es: ['La disciplina importa porque la preferencia puede seguir siendo personal. Dos catadores pueden coincidir en una acidez alta y discrepar sobre si refresca. Anota ambas afirmaciones por separado. Una nota es útil cuando predice una acción: otra temperatura, un plato, un tiempo de aireación o un estilo de contraste. Con el tiempo, esas pequeñas predicciones muestran qué percepciones son estables y cuáles dependen de cansancio, expectativa, comida o copa.', 'Una cata intencionada también puede repetirse después de un bocado. Sal, grasa y proteína cambian la impresión de acidez, tanino y alcohol; anota primero el vino solo. Después vuelve a las mismas preguntas de estructura: qué se suavizó, qué se afiló y qué aroma conectó plato y vino. Así el maridaje sigue siendo una observación comprobable.'],
  },
  'sparkling-methods': {
    en: ['Pressure should be treated as part of the whole wine. A high-acid base can carry extended lees ageing; a softer base may need dosage and bottle time to avoid a broad finish. Tirage, riddling, disgorgement and dosage are not isolated technical nouns: each changes exposure, solids or sweetness. Compare a traditional-method wine with a tank-method wine made from a similar grape, then describe mousse, aroma and finish before assigning a quality judgement.', 'Bottle pressure also changes the pace of pouring and the loss of carbon dioxide. A slow, angled pour protects mousse; a warm glass or repeated topping-up strips it quickly. Dosage should be tasted as a balance with acid and autolytic savour, not as a sweetness category alone. Keep the same pour height and glass when comparing brut, extra-brut or zero-dosage examples.'],
    de: ['Druck gehört zum gesamten Wein. Ein säurereicher Grundwein kann lange Hefereife tragen; ein weicherer braucht vielleicht Dosage und Flaschenzeit, damit der Abgang nicht breit wirkt. Fülldosage, Rütteln, Degorgieren und Dosage sind keine isolierten Fachwörter: Jeder Schritt verändert Kontakt, Feststoffe oder Süße. Vergleiche traditionelle und Tankmethode mit ähnlicher Sorte und beschreibe Mousse, Duft und Abgang, bevor du Qualität urteilst.', 'Flaschendruck verändert auch das Einschenken und den Verlust von Kohlendioxid. Langsames, schräges Eingießen schützt die Mousse; ein warmes Glas oder häufiges Nachschenken leert sie schnell. Dosage sollte als Verhältnis von Süße, Säure und hefiger Würze probiert werden, nicht nur als Kategorie. Halte Höhe und Glas beim Vergleich von Brut, Extra-Brut und ohne Dosage gleich.'],
    fr: ['La pression fait partie du vin entier. Une base très acide supporte un long élevage sur lies ; une base plus souple peut demander dosage et temps en bouteille pour éviter une finale large. Tirage, remuage, dégorgement et dosage ne sont pas des mots isolés : chaque étape change contact, solides ou douceur. Comparez une méthode traditionnelle et une méthode en cuve sur un cépage proche et décrivez mousse, nez et finale avant le jugement de qualité.', 'La pression règle aussi le service et la perte de gaz carbonique. Un versement lent et incliné protège la mousse ; un verre chaud ou des remplissages répétés la dissipent vite. Goûtez le dosage comme un équilibre avec acidité et sapidité autolytique, pas comme un simple niveau de sucre. Gardez hauteur de versement et verre identiques entre brut, extra-brut et non dosé.'],
    es: ['La presión forma parte del vino completo. Un vino base con mucha acidez soporta crianza larga sobre lías; una base más suave quizá necesite dosage y tiempo en botella para no terminar ancho. Tiraje, removido, degüelle y dosage no son palabras aisladas: cada paso cambia contacto, sólidos o dulzor. Compara método tradicional y de tanque con una variedad parecida y describe mousse, aroma y final antes de juzgar calidad.', 'La presión también cambia el servicio y la pérdida de dióxido de carbono. Un vertido lento e inclinado conserva mousse; una copa caliente o rellenar repetidamente la pierde rápido. Prueba el dosage como equilibrio entre dulzor, acidez y sabor autolítico, no solo como categoría azucarada. Mantén altura y copa iguales al comparar brut, extra-brut y sin dosage.'],
  },
  'red-white-rose': {
    en: ['Acidity and pH help explain why two wines of similar colour can feel different. A lower pH supports brighter colour and sharper freshness, while extraction and alcohol can add grip and weight. Press fractions, skin health, seed maturity and oxygen exposure all alter the result. When teaching colour, show a direct-pressed rosé beside a skin-fermented red and ask guests to identify structure separately from hue.'],
    de: ['Säure und pH erklären, warum zwei ähnlich gefärbte Weine verschieden wirken. Niedrigerer pH stabilisiert oft leuchtendere Farbe und straffere Frische, während Extraktion und Alkohol Griff und Gewicht geben. Pressfraktionen, Schalengesundheit, Kernreife und Sauerstoffkontakt verändern das Ergebnis. Zeige beim Unterrichten einen direkt gepressten Rosé neben einem schalenvergorenen Rotwein und lasse Struktur getrennt von Farbton benennen.'],
    fr: ['Acidité et pH expliquent pourquoi deux vins de couleur proche peuvent avoir un toucher différent. Un pH plus bas soutient souvent une couleur vive et une fraîcheur plus tranchante, tandis qu’extraction et alcool ajoutent prise et poids. Fractions de presse, état des peaux, maturité des pépins et oxygène changent le résultat. Pour enseigner la couleur, placez un rosé pressé directement à côté d’un rouge macéré et faites distinguer structure et teinte.'],
    es: ['Acidez y pH explican por qué dos vinos de color parecido pueden sentirse distintos. Un pH menor suele sostener color más vivo y frescura más afilada, mientras extracción y alcohol añaden agarre y peso. Fracciones de prensa, sanidad de pieles, madurez de semillas y oxígeno cambian el resultado. Para enseñar color, sirve un rosado de prensado directo junto a un tinto fermentado con pieles y pide separar estructura de tono.'],
  },
  'sweet-wine': {
    en: ['Sweetness should be assessed after acidity and temperature, not before them. Chilling can reduce the immediate impression of sugar while sharpening acid; warming releases concentrated fruit and alcohol. A dessert wine may be sweet because grapes were botrytised, frozen, dried or picked late, and each route leaves a different balance of extract and aroma. A small, clean glass makes the comparison fair.'],
    de: ['Süße sollte nach Säure und Temperatur beurteilt werden, nicht davor. Kühlen mindert den unmittelbaren Zuckereindruck und schärft Säure; Erwärmen löst konzentrierte Frucht und Alkohol. Dessertwein kann aus Botrytis, Gefrieren, Trocknen oder später Lese stammen, und jeder Weg hinterlässt ein anderes Verhältnis von Extrakt und Duft. Ein kleines, sauberes Glas macht den Vergleich fair.'],
    fr: ['Évaluez la douceur après l’acidité et la température. Le froid atténue l’impression immédiate de sucre et accentue l’acidité ; la chaleur libère fruit concentré et alcool. Un vin de dessert peut venir de botrytis, de gel, de séchage ou d’une vendange tardive, chaque voie laissant un rapport différent entre extrait et arômes. Un petit verre propre rend la comparaison juste.'],
    es: ['Evalúa el dulzor después de la acidez y la temperatura. El frío reduce la impresión inmediata de azúcar y afila la acidez; el calor libera fruta concentrada y alcohol. Un vino de postre puede proceder de botritis, congelación, secado o vendimia tardía, y cada ruta deja otra relación entre extracto y aromas. Una copa pequeña y limpia hace justo el contraste.'],
  },
  'fortified-wine': {
    en: ['Fortified wine rewards a two-part question: what was the base, and what did spirit plus time do to it? Grape, fermentation dryness, fortification point and vessel set the starting line. Flor, ullage, evaporation and bottle ageing then create different aromatic clocks. Serve a little and let the finish settle; alcohol warmth can arrive before sweetness, or sweetness can soften alcohol when acid is sufficient.', 'Storage after opening depends on style. A flor-protected dry wine loses its freshness on air faster than a sweet, oxidative style; a bottle-aged wine with sediment needs standing and a careful pour. Compare ruby, tawny, Fino or Madeira by colour, oxygen history, sweetness and final warmth, not by alcohol percentage alone.'],
    de: ['Verstärkter Wein verlangt zwei Fragen: Was war die Basis, und was bewirkten Spiritus und Zeit? Sorte, Gärtrockenheit, Aufspritzzeitpunkt und Gefäß legen den Anfang fest. Flor, Kopfraum, Verdunstung und Flaschenreife erzeugen danach verschiedene Aromauhren. Schenke wenig ein und lasse den Abgang ausklingen; Alkoholwärme kann vor Süße eintreffen, oder Säure kann Alkohol neben Süße abpuffern.', 'Auch die Lagerung nach dem Öffnen folgt dem Stil. Ein flor-geschützter trockener Wein verliert an Luft schneller Frische als ein süßer oxidativer; ein Flaschenwein mit Depot braucht Aufrechtstellen und vorsichtiges Ausschenken. Vergleiche Ruby, Tawny, Fino und Madeira nach Farbe, Sauerstoffgeschichte, Süße und Wärme, nicht nur nach Alkoholprozent.'],
    fr: ['Un vin fortifié appelle deux questions : quelle était la base, et que font l’eau-de-vie et le temps ? Cépage, sécheresse de fermentation, moment du mutage et contenant fixent le départ. Flor, vide, évaporation et bouteille créent ensuite des horloges aromatiques différentes. Servez peu et laissez la finale se poser ; l’alcool peut arriver avant la douceur, ou l’acidité peut le contenir. Observez aussi la couleur, la note oxydative et la sensation saline pour reconstruire le parcours.', 'La conservation après ouverture dépend du style. Un sec protégé par flor perd sa fraîcheur à l’air plus vite qu’un doux oxydatif ; un vin de bouteille avec dépôt demande repos vertical et versement lent. Comparez ruby, tawny, Fino et Madère par couleur, histoire d’oxygène, douceur et chaleur finale, pas seulement par degré alcoolique.'],
    es: ['Un vino fortificado pide dos preguntas: cuál era la base y qué hicieron el alcohol añadido y el tiempo. Variedad, sequedad de fermentación, momento del encabezado y recipiente fijan el comienzo. Flor, espacio de aire, evaporación y botella crean relojes aromáticos distintos. Sirve poca cantidad y deja asentarse el final; el alcohol puede llegar antes que el dulzor, o la acidez puede contenerlo. Observa también color, nota oxidativa y sensación salina para reconstruir su recorrido.', 'La conservación tras abrir depende del estilo. Un seco protegido por flor pierde frescura con aire antes que uno dulce y oxidativo; un vino de botella con poso exige mantenerlo vertical y servir despacio. Compara ruby, tawny, Fino y Madeira por color, historia de oxígeno, dulzor y calor final, no solo por graduación.'],
  },
  service: {
    en: ['Serving is part of interpretation. Record bottle age, opening time, temperature, glass and whether food is present, because each can alter the signal. If a wine seems closed, warm a small portion rather than exposing the whole bottle; if alcohol dominates, cool it before deciding that the wine is unbalanced. A host can offer a second pour after ten minutes and ask guests to describe the change in acid, aroma and finish.'],
    de: ['Servieren gehört zur Interpretation. Notiere Flaschenalter, Öffnungszeit, Temperatur, Glas und Speisen, weil jedes den Eindruck verändert. Wirkt ein Wein verschlossen, erwärme eine kleine Menge statt die ganze Flasche zu belüften; dominiert Alkohol, kühle vor dem Urteil. Ein Host kann nach zehn Minuten nachschenken und die Gäste nach Säure, Duft und Abgang fragen.'],
    fr: ['Le service fait partie de l’interprétation. Notez âge de la bouteille, heure d’ouverture, température, verre et présence d’un plat, car chacun change le signal. Si le vin paraît fermé, réchauffez une petite dose plutôt que toute la bouteille ; si l’alcool domine, rafraîchissez avant de conclure. Un hôte peut resservir après dix minutes et faire décrire l’évolution de l’acidité, du nez et de la finale. Gardez le même ordre de service afin que la fatigue du palais ne devienne pas une prétendue différence de style.'],
    es: ['Servir forma parte de interpretar. Anota edad de la botella, hora de apertura, temperatura, copa y presencia de comida, porque cada factor cambia la señal. Si el vino parece cerrado, calienta una pequeña cantidad en vez de airear toda la botella; si domina el alcohol, enfría antes de juzgar. El anfitrión puede volver a servir a los diez minutos y pedir describir cambio de acidez, aroma y final.'],
  },
  'glassware-anatomy': {
    en: ['The most useful glass is the one whose effect can be repeated. Mark the fill line, use equal temperature and swap the order of glasses halfway through. A broad bowl may amplify ripe fruit but also reveal volatile acidity; a narrow rim may concentrate floral notes while hiding reduction. If guests disagree, ask which aroma, texture or warmth changed rather than which glass is best.', 'Compare the glass at two fill levels before drawing a conclusion. A low pour has more headspace and warms faster relative to its volume; a high pour reduces air above the wine but can make swirling awkward. Record whether the effect appears in aroma only, or also in acidity, alcohol and finish. A shape that flatters one service size may fail at another.'],
    de: ['Das nützlichste Glas ist das, dessen Wirkung wiederholbar ist. Markiere die Füllhöhe, gleiche die Temperatur an und vertausche die Reihenfolge zur Hälfte. Ein breiter Kelch verstärkt reife Frucht, kann aber auch flüchtige Säure zeigen; ein enger Rand sammelt Blütennoten und verbirgt vielleicht Reduktion. Bei Uneinigkeit frage, welcher Duft, welche Textur oder Wärme sich änderte, nicht welches Glas besser ist.', 'Vergleiche den Kelch bei zwei Füllhöhen, bevor du urteilst. Eine kleine Menge besitzt relativ mehr Kopfraum und erwärmt sich schneller; eine hohe Füllung verringert die Luft über dem Wein, erschwert aber das Schwenken. Notiere, ob der Unterschied nur im Duft oder auch in Säure, Alkohol und Abgang erscheint. Eine Form kann bei einer Menge passen und bei einer anderen versagen.'],
    fr: ['Le verre utile est celui dont l’effet se répète. Marquez le niveau, égalisez la température et inversez l’ordre à mi-parcours. Un large calice peut amplifier le fruit mûr mais aussi la volatile ; un bord resserré concentre les fleurs tout en cachant parfois la réduction. En cas de désaccord, demandez quel arôme, quelle texture ou quelle chaleur change, plutôt que quel verre est meilleur.', 'Comparez le calice à deux niveaux de remplissage avant de conclure. Une petite dose possède proportionnellement plus d’espace de tête et se réchauffe plus vite ; une dose haute réduit l’air mais gêne le mouvement. Notez si l’écart concerne seulement le nez ou aussi acidité, alcool et finale. Une forme flatteuse pour un volume peut échouer avec un autre.'],
    es: ['La copa más útil es la que produce un efecto repetible. Marca el nivel, iguala temperatura y cambia el orden a mitad de la prueba. Un cáliz ancho puede amplificar fruta madura, pero también acidez volátil; un borde estrecho concentra flores y quizá oculta reducción. Si hay desacuerdo, pregunta qué aroma, textura o calor cambió, no qué copa es mejor.', 'Compara la copa con dos niveles de llenado antes de concluir. Un servicio bajo tiene más espacio de cabeza relativo y se calienta antes; uno alto reduce aire, pero dificulta agitar. Anota si el efecto aparece solo en aroma o también en acidez, alcohol y final. Una forma que funciona con un volumen puede fallar con otro.'],
  },
  'aroma-language': {
    en: ['Vocabulary becomes trustworthy when it helps another person find the same reference. Use a real sample, an image or a concise comparison, and avoid treating a descriptor as a chemical diagnosis. Vanilla suggests an association that may involve oak, while cassis leaf can invite a grape or ripeness hypothesis; neither proves its source. Say reminiscent of when evidence is sensory rather than analytical.', 'Calibration is easier when the same reference is smelled at several intensities. A faint smell may disappear when the wine is cold, while warming can make a family seem more certain than it is. Record intensity and confidence separately, and return to the first reference after tasting another wine. This keeps a dramatic late aroma from rewriting the earlier observation.'],
    de: ['Wortschatz wird verlässlich, wenn eine andere Person dieselbe Referenz finden kann. Verwende eine echte Probe, ein Bild oder einen kurzen Vergleich und behandle den Deskriptor nicht als chemische Diagnose. Vanille kann mit Holz zusammenhängen, Johannisbeerblatt eine Sorten- oder Reifehypothese auslösen; beides beweist die Quelle nicht. Erinnert an ist ehrlich, wenn der Beleg sensorisch und nicht analytisch ist.', 'Kalibrierung gelingt besser, wenn dieselbe Referenz in verschiedenen Stärken gerochen wird. Ein schwacher Duft verschwindet bei Kälte, während Erwärmung eine Aromafamilie sicherer erscheinen lässt, als sie ist. Notiere Intensität und Sicherheit getrennt und kehre nach einem anderen Wein zur ersten Referenz zurück. So überschreibt ein später, dramatischer Duft nicht den frühen Befund.'],
    fr: ['Le vocabulaire devient fiable lorsqu’il aide quelqu’un à retrouver la même référence. Utilisez un échantillon réel, une image ou une comparaison courte, sans transformer le descripteur en diagnostic chimique. Vanille peut évoquer le bois ; feuille de cassis peut suggérer cépage ou maturité, sans prouver l’origine. Dites rappelle lorsque la preuve est sensorielle et non analytique.', 'La calibration est plus solide lorsque la même référence est sentie à plusieurs intensités. Un parfum faible disparaît avec le froid, tandis que le réchauffement peut donner une certitude excessive. Notez intensité et confiance séparément, puis revenez à la référence après un autre vin. Un arôme tardif et spectaculaire ne doit pas réécrire la première observation. La description gagne en portée lorsqu’elle indique aussi la durée et la netteté du parfum.'],
    es: ['El vocabulario se vuelve fiable cuando ayuda a otra persona a encontrar la misma referencia. Usa una muestra real, una imagen o una comparación breve y no conviertas el descriptor en diagnóstico químico. Vainilla puede sugerir madera; hoja de grosella puede abrir una hipótesis de variedad o madurez, pero ninguna prueba el origen. Di recuerda a cuando la evidencia sea sensorial.', 'La calibración mejora si hueles la misma referencia con distintas intensidades. Un olor tenue puede desaparecer en frío, mientras el calentamiento hace que una familia parezca más segura de lo que es. Anota intensidad y confianza por separado y vuelve a la referencia después de probar otro vino. Así un aroma tardío y llamativo no reescribe la primera observación.'],
  },
  'vine-year': {
    en: ['A vintage note should keep the calendar visible. Frost before flowering, rain at flowering, heat during véraison and humidity near harvest create different biological problems. Growers respond with pruning, canopy work, crop adjustment, irrigation, selection or picking date, and the response can matter as much as the event. Two producers in one valley may therefore make different wines from the same weather.'],
    de: ['Eine Jahrgangsnotiz sollte den Kalender sichtbar halten. Frost vor der Blüte, Regen während der Blüte, Hitze zur Véraison und Feuchte vor der Lese erzeugen verschiedene biologische Probleme. Erzeuger reagieren mit Schnitt, Laubarbeit, Ertragsanpassung, Bewässerung, Selektion oder Lesezeitpunkt; die Reaktion zählt ebenso wie das Ereignis. Zwei Betriebe im selben Tal können daher aus demselben Wetter verschiedene Weine erzeugen.'],
    fr: ['Un commentaire de millésime doit garder le calendrier visible. Gel avant floraison, pluie pendant la floraison, chaleur à la véraison et humidité avant récolte posent des problèmes biologiques différents. Le vigneron répond par taille, feuillage, charge, irrigation, tri ou date de vendange ; cette réponse compte autant que l’événement. Deux domaines d’une même vallée peuvent donc produire des vins différents sous la même météo.'],
    es: ['Una nota de añada debe mantener visible el calendario. Helada antes de floración, lluvia durante floración, calor en envero y humedad cerca de vendimia crean problemas biológicos distintos. El viticultor responde con poda, manejo de hojas, ajuste de carga, riego, selección o fecha de cosecha; la respuesta importa tanto como el evento. Dos productores del mismo valle pueden hacer vinos distintos con el mismo tiempo.'],
  },
  'terroir-layers': {
    en: ['Origin claims become stronger when the comparison is designed. Keep variety, rootstock and cellar method close, then compare slope, depth, exposure or water access across more than one year. If the difference disappears in a wet season, water status may be part of the explanation; if it persists, structure, mesoclimate or farming may matter. A named soil is a starting question, not a flavour ingredient.'],
    de: ['Herkunftsbehauptungen werden stärker, wenn der Vergleich geplant ist. Halte Sorte, Unterlage und Kellerweg ähnlich und vergleiche Hang, Tiefe, Exposition oder Wasserzugang über mehrere Jahre. Verschwindet der Unterschied in einem nassen Jahr, kann Wasserstatus erklären; bleibt er, zählen vielleicht Struktur, Mesoklima oder Bewirtschaftung. Ein Bodenname ist eine Startfrage, kein Geschmacksstoff.'],
    fr: ['Les affirmations d’origine gagnent en force lorsque la comparaison est conçue. Gardez cépage, porte-greffe et méthode de chai proches, puis comparez pente, profondeur, exposition ou accès à l’eau sur plusieurs années. Si l’écart disparaît lors d’une saison humide, l’état hydrique compte peut-être ; s’il persiste, structure, mésoclimat ou conduite jouent peut-être. Un sol nommé est une question de départ, pas un ingrédient aromatique.'],
    es: ['Las afirmaciones de origen son más sólidas si el contraste está diseñado. Mantén parecidas variedad, portainjerto y método de bodega; compara pendiente, profundidad, exposición o acceso al agua durante varios años. Si la diferencia desaparece en una temporada húmeda, puede explicarla el estado hídrico; si persiste, quizá importan estructura, mesoclima o manejo. Un suelo nombrado es una pregunta inicial, no un ingrediente aromático.'],
  },
  fermentation: {
    en: ['Fermentation logs turn a story into evidence: start density, nutrient additions, temperature curve, cap work, sulfur smell and final residual sugar. A tasting room need not expose every measurement, but one clear graph can explain why a white is aromatic or a red has firm extraction. Use a retained sample whenever an intervention is made so the consequence can be tasted rather than imagined.'],
    de: ['Gärprotokolle machen aus der Geschichte einen Beleg: Anfangsdichte, Nährstoffe, Temperaturkurve, Hutbewegung, Schwefelgeruch und Restzucker. Im Verkostungsraum muss nicht jeder Messwert gezeigt werden, aber eine klare Kurve kann erklären, warum ein Weißwein duftig oder ein Rotwein fest extrahiert ist. Bei jedem Eingriff hilft eine Vergleichsprobe, damit die Folge probiert und nicht nur behauptet wird.'],
    fr: ['Un journal de fermentation transforme le récit en preuve : densité initiale, nutriments, courbe de température, travail du chapeau, odeur soufrée et sucre final. La salle de dégustation n’a pas besoin de tout montrer, mais un graphique clair explique pourquoi un blanc est aromatique ou un rouge extrait. Gardez une cuve témoin lors d’une intervention pour goûter la conséquence.'],
    es: ['El registro de fermentación convierte el relato en evidencia: densidad inicial, nutrientes, curva de temperatura, manejo del sombrero, olor sulfuroso y azúcar final. No hace falta mostrar cada dato, pero una gráfica clara explica por qué un blanco es aromático o un tinto tiene extracción firme. Conserva una muestra testigo cuando intervengas para probar la consecuencia y no imaginarla.'],
  },
  'maturation-vessels': {
    en: ['A vessel cannot be separated from maintenance. Clean surfaces, topping-up, headspace, temperature and transfer frequency determine whether the intended oxygen regime survives. New oak may be quiet after several fills, while a neutral tank can still produce reduction if the wine is protected too completely. Treat the vessel as a set of conditions and record the wine before and after each move.'],
    de: ['Ein Gefäß ist nicht von seiner Pflege zu trennen. Saubere Oberflächen, Auffüllen, Kopfraum, Temperatur und Umfüllhäufigkeit bestimmen, ob der gewünschte Sauerstoffhaushalt erhalten bleibt. Neues Holz kann nach mehreren Füllungen neutral werden; ein Tank kann bei zu vollständigem Schutz dennoch Reduktion fördern. Betrachte das Gefäß als Bündel von Bedingungen und notiere den Wein vor und nach jedem Umzug.'],
    fr: ['Un contenant ne peut être séparé de son entretien. Propreté, ouillage, espace de tête, température et fréquence des transferts décident si le régime d’oxygène voulu persiste. Un bois neuf peut devenir discret après plusieurs remplissages ; une cuve neutre peut pourtant réduire si le vin est trop protégé. Considérez le contenant comme un ensemble de conditions et notez le vin avant et après chaque mouvement. Un essai parallèle doit garder le même niveau de remplissage, sinon l’espace d’air masque l’effet du matériau.'],
    es: ['Un recipiente no se separa de su mantenimiento. Limpieza, relleno, espacio de cabeza, temperatura y frecuencia de trasiegos deciden si sobrevive el régimen de oxígeno buscado. La madera nueva puede volverse discreta tras varios usos; un depósito neutro también puede reducir si el vino está demasiado protegido. Trata el recipiente como un conjunto de condiciones y anota el vino antes y después de cada movimiento.'],
  },
  'lees-and-malolactic': {
    en: ['Texture is easier to teach when “soft” is unpacked. Lees can add breadth, suspension and a creamy impression; malolactic conversion lowers malic sharpness and may change aroma; oak and alcohol can create similar warmth. Ask whether the finish is creamy, salty, drying or merely less acidic. That vocabulary prevents a buttery shortcut from erasing the distinct chemistry and management behind each choice.', 'Reduction and microbial spoilage can both make a lees-aged wine difficult to read. A struck-match note may lift with careful oxygen, while volatile acidity or mousiness will not be corrected by calling the wine creamy. Check clarity, smell and acidity in a fresh sample, then compare after the wine has settled.', 'Measure before naming the texture. A turbidity reading, malic-acid test, pH, free sulfur and volatile-acidity result can show whether a change follows stirring, bacterial conversion or contamination. Keep a quiet control sample and taste both after the same time; otherwise a temporary suspension of solids may be mistaken for lasting autolytic volume.'],
    de: ['Textur lässt sich besser erklären, wenn „weich“ zerlegt wird. Hefetrub kann Breite, Schwebestoffe und Cremigkeit geben; Malo mindert Apfelsäureschärfe und kann Aroma ändern; Holz und Alkohol erzeugen ähnliche Wärme. Frage, ob der Abgang cremig, salzig, trocknend oder nur weniger säurebetont ist. So ersetzt ein Butterwort nicht die unterschiedliche Chemie und Führung der Prozesse.', 'Reduktion und mikrobielle Fehler können einen Wein auf der Hefe gleichermaßen schwer lesbar machen. Ein Streichholzton kann sich bei vorsichtigem Sauerstoff heben; flüchtige Säure oder Mäuseln werden dagegen nicht durch das Wort cremig geheilt. Prüfe Klarheit, Geruch und Säure an einer frischen Probe und vergleiche nach dem Absetzen erneut.', 'Vor dem Urteil helfen Messwerte: Trübung, Apfelsäure, pH, freier Schwefel und flüchtige Säure zeigen, ob eine Veränderung Aufrühren, Bakterien oder Verunreinigung folgt. Halte eine ruhige Kontrollprobe zurück und verkoste beide nach gleicher Zeit; sonst wird vorübergehend schwebender Trub mit dauerhafter Autolysetextur verwechselt.'],
    fr: ['La texture s’enseigne mieux lorsque « souple » est décomposé. Les lies peuvent élargir et donner une impression crémeuse ; la malo réduit la vivacité malique et peut changer l’arôme ; bois et alcool créent une chaleur voisine. Demandez si la finale est crémeuse, saline, asséchante ou simplement moins acide. Ce vocabulaire évite qu’un raccourci beurré efface la chimie et la conduite propres à chaque choix.', 'Réduction et altération microbienne peuvent rendre un vin sur lies difficile à lire. Une note de pierre à fusil peut se lever avec un apport d’air mesuré, tandis que volatile ou souris ne se corrigent pas en disant crémeux. Vérifiez limpidité, nez et acidité sur un échantillon frais, puis regoûtez après dépôt des lies.', 'Mesurez avant de nommer la texture : turbidité, acide malique, pH, soufre libre et volatile indiquent si l’effet suit le bâtonnage, les bactéries ou une contamination. Gardez une fraction calme et goûtez les deux après le même délai ; des solides momentanément en suspension peuvent sinon sembler être un volume autolytique durable.'],
    es: ['La textura se enseña mejor si se descompone «suave». Las lías pueden dar amplitud y sensación cremosa; la maloláctica reduce la viveza málica y puede cambiar aroma; madera y alcohol crean calor parecido. Pregunta si el final es cremoso, salino, secante o simplemente menos ácido. Así una palabra mantecosa no borra la química y gestión distintas de cada decisión.', 'La reducción y el deterioro microbiano pueden volver difícil de leer un vino sobre lías. Un tono de cerilla puede levantarse con oxígeno medido, pero la acidez volátil o el carácter de ratón no se arreglan llamándolo cremoso. Comprueba limpidez, nariz y acidez en una muestra fresca y vuelve a probar cuando el sedimento haya asentado.', 'Mide antes de nombrar la textura: turbidez, ácido málico, pH, azufre libre y acidez volátil muestran si el cambio sigue al removido, las bacterias o una contaminación. Conserva una muestra quieta y prueba ambas tras el mismo tiempo; los sólidos suspendidos de forma temporal podrían parecer volumen autolítico duradero.'],
  },
}

const specificExtras: GuideDepthRecord = {
  'sparkling-methods': {
    en: [
      'Traditional-method sparkling wine begins with a still base whose acidity, alcohol and pH must survive another fermentation. Tirage adds sugar and yeast; the bottle is sealed, and the yeast converts that sugar into alcohol and carbon dioxide. Because the gas cannot escape, pressure rises. The dead yeast then forms lees, and autolysis releases compounds associated with bread, biscuit and a more rounded texture. Riddling gathers the deposit in the neck, disgorgement removes it, and dosage replaces lost liquid while setting the final sweetness. Each stage is a physical intervention, not a decorative label. A bottle-fermented wine can therefore show both the freshness of its base and the savoury depth of time on lees.',
      'In the tank method, the second fermentation happens in a pressure vessel, allowing a producer to retain fresh varietal fruit and bottle a larger volume consistently. The wine may have less bottle-specific autolytic development because the contact history is different. Ancestral wines follow another route: they are bottled before the first fermentation is complete, so remaining sugar and yeast finish the work in bottle. Pressure, sediment and microbial stability require close control. To compare methods, use wines with similar sweetness and grape character, then assess mousse persistence, aroma family, texture, acid line and finish. A narrow flute can exaggerate the visual bead while hiding aroma, so a tulip or white-wine glass makes the process easier to taste.'
    ],
    de: [
      'Schaumwein nach traditioneller Methode beginnt mit einem stillen Grundwein, dessen Säure, Alkohol und pH eine weitere Gärung tragen müssen. Die Fülldosage bringt Zucker und Hefe; die Flasche wird verschlossen, und die Hefe wandelt Zucker in Alkohol und Kohlendioxid um. Weil das Gas nicht entweichen kann, steigt der Druck. Die abgestorbene Hefe bildet Trub; Autolyse setzt Stoffe frei, die an Brot, Biskuit und rundere Textur erinnern. Rütteln sammelt das Depot im Flaschenhals, Degorgieren entfernt es, und die Dosage ersetzt Flüssigkeit und bestimmt die endgültige Süße. Jeder Schritt ist ein physischer Eingriff. Flaschenreife kann daher Grundweinfrische und hefige Tiefe zugleich zeigen.',
      'Bei der Tankmethode findet die zweite Gärung im Druckbehälter statt; Sortenfrucht lässt sich in größeren Mengen gleichmäßig bewahren. Die Flaschen besitzen oft weniger individuelle Autolyse, weil der Hefekontakt anders verläuft. Bei der Méthode ancestrale wird abgefüllt, bevor die erste Gärung beendet ist; Restzucker und Hefe arbeiten in der Flasche weiter. Druck, Depot und mikrobielle Stabilität verlangen genaue Kontrolle. Vergleiche Methoden mit ähnlicher Sorte und Süße und beurteile Perlage, Aromafamilie, Textur, Säurelinie und Abgang. Eine Flöte kann die Blasen optisch überhöhen und Duft verbergen; Tulpen- oder Weißweinglas macht den Unterschied schmeckbarer.'
    ],
    fr: [
      'Un effervescent de méthode traditionnelle commence par un vin de base dont acidité, alcool et pH doivent supporter une nouvelle fermentation. La liqueur de tirage apporte sucre et levures ; la bouteille est fermée, les levures transforment le sucre en alcool et gaz carbonique, et la pression monte. Les levures mortes forment les lies ; l’autolyse libère des composés évoquant pain, biscuit et texture plus ronde. Le remuage rassemble le dépôt dans le col, le dégorgement l’évacue, puis le dosage compense la perte et fixe la douceur finale. Chaque étape est physique. Le vin peut ainsi garder la fraîcheur de sa base et la profondeur d’un long contact avec les lies.',
      'En cuve, la seconde fermentation se déroule dans un récipient sous pression, ce qui permet de conserver le fruit du cépage et de produire des lots réguliers. Le développement autolytique propre à chaque bouteille peut être moindre. Dans la méthode ancestrale, on embouteille avant la fin de la première fermentation ; sucre restant et levures terminent le travail en bouteille. Pression, dépôt et stabilité microbienne demandent une surveillance précise. Comparez des vins de cépage et de douceur proches et observez persistance de la mousse, famille aromatique, toucher, ligne acide et finale. Une flûte favorise l’image des bulles mais limite le nez ; un verre tulipe ou à blanc permet de goûter le procédé.'
    ],
    es: [
      'El espumoso de método tradicional comienza con un vino base cuya acidez, alcohol y pH deben soportar otra fermentación. El licor de tiraje añade azúcar y levadura; la botella se cierra, la levadura transforma azúcar en alcohol y dióxido de carbono y sube la presión. La levadura muerta forma lías, y la autólisis libera compuestos de pan, galleta y textura más redonda. El removido reúne el sedimento en el cuello, el degüelle lo elimina y el dosage repone líquido y fija el dulzor final. Cada etapa es física. La botella puede mostrar frescura del vino base y profundidad sabrosa del tiempo sobre lías.',
      'En tanque, la segunda fermentación ocurre en un recipiente a presión, de modo que se conserva fruta varietal y se embotellan lotes grandes con regularidad. Puede haber menos autólisis individual porque cambia el contacto con lías. El método ancestral embotella antes de terminar la primera fermentación; azúcar restante y levaduras acaban el proceso en botella. Presión, sedimento y estabilidad microbiana requieren control. Compara métodos con variedad y dulzor parecidos y describe persistencia de mousse, familia aromática, textura, línea ácida y final. La flauta favorece la imagen de burbujas pero limita el aroma; una copa tulipa o de blanco permite saborear la diferencia.'
    ]
  },
  'sweet-wine': {
    en: [
      'Botrytis cinerea is not simply “sweetness from rot”. In suitable humid mornings and drier afternoons, noble rot punctures berry skins and lets water escape while concentrating sugar, acid and flavour. The fungus also changes aroma chemistry, helping create honey, saffron, dried-apricot and tea associations. If weather stays wet, the same organism can become grey rot and damage fruit, so selection is crucial. Botrytised bunches are often picked in several passes because berries do not develop uniformly. The resulting must may be extremely concentrated yet still balanced when acidity remains high. Taste the sweetness as one part of a system: concentration, acid, alcohol, phenolic bitterness and volatile aroma decide whether the wine feels luminous or heavy.',
      'Late harvest, icewine and dried-grape styles concentrate by different mechanisms. Leaving grapes on the vine allows sugar and flavour to rise but increases disease and weather risk; natural freezing removes water as ice and requires a legally defined cold harvest in many regions; appassimento dries picked grapes and changes the ratio of sugar, acid, skins and sometimes volatile compounds. Fermentation may stop naturally at high alcohol or be arrested by chilling, filtration or fortification, leaving residual sugar. Read the label and production method rather than treating all sweet wines as one category. Serve them cool enough to preserve acidity, in small pours, and compare their finishes: botrytis can be honeyed, icewine crystalline, and dried-grape wine richer and more dried-fruited.'
    ],
    de: [
      'Botrytis cinerea bedeutet nicht einfach „Süße durch Fäulnis“. Bei feuchten Morgen und trockeneren Nachmittagen perforiert Edelfäule die Beerenhaut; Wasser entweicht, Zucker, Säure und Geschmack konzentrieren sich. Der Pilz verändert außerdem die Aromachemie und kann an Honig, Safran, getrocknete Aprikose und Tee erinnern. Bleibt das Wetter nass, wird daraus Graufäule und die Frucht verdirbt; Selektion ist daher entscheidend. Botrytistrauben werden oft in mehreren Durchgängen gelesen, weil sie ungleich reifen. Der Most kann extrem konzentriert sein und durch hohe Säure trotzdem leuchtend wirken. Beurteile Süße als System aus Extrakt, Säure, Alkohol, phenolischer Bitterkeit und flüchtigem Duft.',
      'Spätlese, Eiswein und getrocknete Trauben konzentrieren auf unterschiedliche Weise. Am Stock steigen Zucker und Geschmack, aber Krankheits- und Wetterrisiko wachsen; natürliches Gefrieren entfernt Wasser als Eis und verlangt in vielen Gegenden eine definierte Kälteernte; Appassimento trocknet geerntete Trauben und verändert das Verhältnis von Zucker, Säure, Schalen und flüchtigen Stoffen. Gärung kann bei hohem Alkohol stoppen oder durch Kühlen, Filtration oder Aufspriten beendet werden. Lies Methode und Etikett, statt alle Süßweine gleichzusetzen. Kühle sie so, dass Säure bleibt, schenke klein ein und vergleiche den Abgang: Botrytis wirkt honigartig, Eiswein kristallin, Trockenfruchtwein oft üppiger und getrocknet-fruchtig.'
    ],
    fr: [
      'Botrytis cinerea n’est pas simplement du « sucre issu de la pourriture ». Par matin humide et après-midi sec, la pourriture noble perce la peau et fait perdre de l’eau, concentrant sucre, acidité et saveurs. Le champignon modifie aussi la chimie aromatique et peut évoquer miel, safran, abricot sec et thé. Si l’humidité persiste, la pourriture grise abîme le fruit : le tri devient essentiel. Les grappes botrytisées sont souvent cueillies par passages, car les baies n’évoluent pas ensemble. Le moût peut être très concentré tout en gardant de l’éclat grâce à son acidité. Goûtez la douceur avec extrait, acidité, alcool, amertume phénolique et arômes volatils.',
      'Vendange tardive, vin de glace et raisins séchés concentrent par des mécanismes différents. Laisser les grappes mûrir augmente sucre et saveur mais accroît risque de pluie et de maladie ; le gel naturel retire l’eau sous forme de glace ; l’appassimento sèche les raisins récoltés et change les rapports entre sucre, acide, pellicule et composés volatils. La fermentation peut s’arrêter à fort degré ou être arrêtée par froid, filtration ou mutage, laissant du sucre résiduel. Lisez méthode et étiquette plutôt que de réunir tous les doux. Servez frais, en petite quantité, et comparez la finale : botrytis évoque miel, glace précision cristalline, raisin sec fruit confit.'
    ],
    es: [
      'Botrytis cinerea no es simplemente «dulzor de podredumbre». Con mañanas húmedas y tardes secas, la podredumbre noble perfora la piel y deja escapar agua, concentrando azúcar, acidez y sabor. El hongo también cambia la química aromática y puede recordar a miel, azafrán, albaricoque seco y té. Si persiste la humedad, aparece podredumbre gris y se estropea la fruta, por lo que la selección es decisiva. Las uvas botritizadas suelen vendimiarse en varias pasadas porque no maduran a la vez. El mosto puede ser muy concentrado y seguir luminoso cuando conserva acidez. Prueba dulzor junto a extracto, acidez, alcohol, amargor fenólico y aroma volátil.',
      'Vendimia tardía, vino de hielo y estilos de uva seca concentran por mecanismos distintos. Dejar la uva en la planta eleva azúcar y sabor, pero aumenta riesgo de lluvia y enfermedad; la congelación natural retira agua como hielo; el appassimento seca uva cosechada y cambia relaciones entre azúcar, acidez, piel y compuestos volátiles. La fermentación puede pararse por alcohol o mediante frío, filtración o encabezado, dejando azúcar residual. Lee método y etiqueta, no juntes todos los dulces. Sirve fresco y en poca cantidad; compara el final: botritis puede ser melosa, hielo cristalino y uva seca más opulenta y de fruta confitada.'
    ]
  },
  'fortified-wine': {
    en: [
      'Fortification is a timing decision. If spirit is added while fermentation still contains sugar, as in Port production, the rising alcohol stops or inhibits yeast and preserves sweetness. If spirit is added after a dry fermentation, the base remains dry and the added alcohol becomes part of a more oxidative or saline style. The amount and strength of grape spirit, the temperature of addition and the mixing process affect integration. A high-alcohol wine can still feel balanced when acidity, extract and bitterness provide a frame; without that frame, alcohol smells hot and shortens the finish. Taste the same style at different temperatures because warmth releases alcohol faster than many fruit aromas.',
      'Flor, oxidative casks and solera blending are distinct ageing systems. A biological film can reduce direct oxygen contact and create aldehydic, almond-like and savoury notes; an ullage-filled cask allows oxygen and evaporation, concentrating colour and flavour; a solera blends fractions of different ages so continuity matters more than one vintage. Madeira adds heat and oxidation as deliberate tools, while a bottle-aged Port develops sediment and tertiary fruit under a different oxygen regime. Labels such as fino, tawny, ruby or colheita are clues, not tasting conclusions. Ask what the base wine was, when spirit arrived, what vessel protected or exposed it, and whether sweetness is balanced by acid rather than masked by alcohol.'
    ],
    de: [
      'Aufspriten ist eine Frage des Zeitpunkts. Wird Spirituose zugesetzt, solange noch Zucker gärt, wie bei Port, stoppt oder hemmt der steigende Alkohol die Hefe und bewahrt Süße. Nach einer trockenen Gärung bleibt die Basis trocken; der zusätzliche Alkohol gehört dann zu einem eher oxidativen oder salzigen Stil. Menge und Stärke des Weinbrands, Temperatur und Durchmischung bestimmen die Einbindung. Viel Alkohol kann ausgewogen wirken, wenn Säure, Extrakt und Bitterkeit einen Rahmen geben; ohne ihn riecht er heiß und verkürzt den Abgang. Probiere denselben Stil bei verschiedener Temperatur, weil Wärme Alkohol schneller freisetzt als viele Fruchtaromen.',
      'Flor, oxidative Fässer und Solera sind verschiedene Alterungssysteme. Ein biologischer Film begrenzt direkten Sauerstoff und erzeugt aldehydische, mandelige und herzhafte Noten; ein Fass mit Kopfraum lässt Sauerstoff und Verdunstung zu und konzentriert Farbe und Geschmack; eine Solera mischt Altersstufen, sodass Kontinuität wichtiger ist als ein einzelner Jahrgang. Madeira nutzt Hitze und Oxidation bewusst, Flaschenport entwickelt Depot und tertiäre Frucht unter anderem Sauerstoffregime. Fino, Tawny, Ruby oder Colheita sind Hinweise, kein Urteil. Frage nach Basis, Zeitpunkt des Aufspritzens, Gefäß und Schutz oder Exposition; prüfe, ob Süße von Säure getragen und nicht von Alkohol verdeckt wird.'
    ],
    fr: [
      'Le mutage est une question de moment. Si l’eau-de-vie arrive pendant qu’il reste du sucre, comme dans le Porto, l’alcool croissant arrête ou inhibe les levures et conserve la douceur. Ajoutée après fermentation sèche, elle laisse une base sèche et devient partie d’un style plus oxydatif ou salin. Dose et degré de l’eau-de-vie, température et mélange déterminent l’intégration. Un vin alcoolisé peut rester équilibré si acidité, extrait et amertume lui donnent une charpente ; sans elle, l’alcool paraît chaud et raccourcit la finale. Servez un même style à deux températures : la chaleur libère l’alcool plus vite que certains fruits.',
      'Flor, fûts oxydatifs et solera sont des systèmes d’élevage différents. Un voile biologique limite l’oxygène direct et crée notes aldéhydiques, amande et savoury ; un fût avec vide laisse entrer air et évaporation, concentrant couleur et goût ; une solera mélange des âges et privilégie continuité plutôt qu’un millésime. Madère utilise chaleur et oxydation comme outils, tandis qu’un Porto en bouteille développe dépôt et fruit tertiaire avec un autre régime. Fino, tawny, ruby et colheita sont des indices. Demandez quelle base, quel moment de mutage, quel contenant et quel équilibre sucre-acidité expliquent le verre, plutôt que d’attribuer toute chaleur à l’âge.'
    ],
    es: [
      'El encabezado depende del momento. Si se añade aguardiente mientras queda azúcar, como en Oporto, el alcohol creciente detiene o inhibe la levadura y conserva dulzor. Si llega después de una fermentación seca, la base queda seca y el alcohol forma parte de un estilo más oxidativo o salino. Cantidad y graduación del destilado, temperatura y mezcla determinan integración. Un vino con mucho alcohol puede equilibrarse con acidez, extracto y amargor; sin ese marco, huele caliente y acorta el final. Prueba el mismo estilo a distintas temperaturas: el calor libera alcohol antes que muchos aromas de fruta.',
      'Flor, botas oxidativas y solera son sistemas de crianza diferentes. Una película biológica limita oxígeno directo y crea notas aldehídicas, de almendra y sabrosas; una bota con espacio de aire permite oxígeno y evaporación y concentra color y sabor; una solera mezcla edades y busca continuidad más que una añada. Madeira usa calor y oxidación deliberadamente, mientras Oporto de botella desarrolla poso y fruta terciaria con otra exposición. Fino, tawny, ruby y colheita orientan, pero no concluyen. Pregunta por la base, el momento del encabezado, el recipiente y si la acidez equilibra dulzor en lugar de dejar que el alcohol lo oculte.'
    ]
  },
  service: additions['service-detail'],
  'glassware-anatomy': {
    en: [
      'A controlled pour is a better glass test than a full restaurant serving. Use the same wine and volume, leave one bowl at a fixed fill line and deliberately vary headspace in the other. Smell without movement, then make one identical swirl. If the broad bowl increases aroma but also makes alcohol feel hotter, record both effects; if neither changes, that null result is useful. Repeating the test after the wine warms separates geometry from temperature and prevents a preferred shape from becoming a universal rule.',
      'Glass shape cannot correct a mismatch between wine and expectation. A fragile older wine may lose detail in a large bowl, while a young reductive wine may need more air before its fruit is readable. Sparkling wines also lose pressure as they stand, so compare them quickly and note the pour height. The practical choice balances sensory gain with stability, washing, storage and the chance that every guest receives the same vessel.',
      'The palate can be part of the glass comparison too. A thick rim may change where wine first lands and how quickly it spreads, while a narrow opening can encourage a smaller sip. Keep the same sip size and swallowing decision, then ask whether acidity, tannin or warmth—not only aroma—changed. A visually elegant glass is not automatically the most informative one.'
    ],
    de: [
      'Ein kontrollierter Ausschank prüft Glaswirkung besser als ein voller Restaurantkelch. Verwende denselben Wein und dieselbe Menge, markiere in einem Kelch eine Fülllinie und verändere im anderen bewusst den Kopfraum. Rieche ohne Bewegung und schwenke dann identisch. Verstärkt der breite Kelch Duft, lässt aber Alkohol wärmer erscheinen, notiere beide Folgen; bleibt alles gleich, ist auch dieses Nullergebnis nützlich. Wiederhole nach dem Erwärmen, um Form und Temperatur zu trennen.',
      'Glasform korrigiert keine falsche Erwartung. Ein fragiler alter Wein kann im großen Kelch Kontur verlieren, während ein junger reduktiver Wein mehr Luft braucht, bis Frucht erscheint. Schaumwein verliert beim Stehen Druck; vergleiche daher rasch und notiere die Ausschankhöhe. Die praktische Wahl verbindet Sinnesgewinn mit Stabilität, Waschen, Lagerung und der Möglichkeit, allen Gästen dieselbe Form zu geben.',
      'Auch der Mundkontakt zählt. Ein dicker Rand verändert, wo der Wein zuerst auftrifft, ein enger Rand kann kleinere Schlucke fördern. Halte Schluckmenge und Schluckweise gleich und frage, ob sich neben dem Duft auch Säure, Tannin oder Wärme ändern. Ein elegantes Glas ist deshalb nicht automatisch das informativste. Ein Vergleich mit Wasser oder einer neutralen Probe zeigt, ob die Form selbst oder nur der Wein den Eindruck prägt.'
    ],
    fr: [
      'Une dose contrôlée teste mieux le verre qu’un grand service de restaurant. Prenez le même vin et le même volume, marquez un niveau fixe dans un calice et faites varier volontairement l’espace de tête dans l’autre. Sentez sans mouvement puis effectuez le même tour. Si le calice large augmente le nez mais rend l’alcool plus chaud, notez les deux effets ; si rien ne change, ce résultat nul est informatif. Répétez après réchauffement pour séparer forme et température.',
      'La forme ne corrige pas une attente mal accordée au vin. Un vieux vin fragile peut perdre sa définition dans un grand calice ; un jeune vin réducteur peut demander de l’air avant que le fruit apparaisse. Les effervescents perdent aussi de la pression en attendant : comparez vite et notez la hauteur de versement. Le choix pratique combine gain sensoriel, stabilité, lavage, rangement et disponibilité de la même forme pour tous.',
      'Le contact avec la bouche compte aussi. Un bord épais modifie le premier point d’arrivée du vin ; une ouverture étroite peut encourager une plus petite gorgée. Gardez dose et manière de boire constantes et demandez si acidité, tanin ou chaleur changent, pas seulement le nez. Un verre élégant n’est donc pas forcément le plus informatif. Un témoin d’eau ou de vin neutre aide à distinguer l’effet du verre de celui du vin.'
    ],
    es: [
      'Un servicio controlado prueba mejor la copa que un llenado de restaurante. Usa el mismo vino y volumen, marca una línea en un cáliz y cambia deliberadamente el espacio de cabeza en el otro. Huele sin mover y después agita igual. Si el cáliz ancho aumenta aroma pero hace más caliente el alcohol, anota ambos efectos; si no cambia nada, el resultado nulo también informa. Repite cuando el vino se caliente para separar geometría y temperatura.',
      'La forma no corrige una expectativa inadecuada. Un vino viejo y frágil puede perder definición en un cáliz grande; uno joven y reductivo puede necesitar aire antes de mostrar fruta. Los espumosos también pierden presión mientras esperan: compáralos pronto y anota la altura del servicio. La elección práctica equilibra ganancia sensorial, estabilidad, lavado, almacenamiento y que todos reciban la misma copa.',
      'El contacto con la boca también cuenta. Un borde grueso cambia dónde llega primero el vino y una abertura estrecha puede favorecer un sorbo menor. Mantén iguales cantidad y forma de beber y pregunta si cambian acidez, tanino o calor, no solo el aroma. Una copa elegante no es automáticamente la más informativa. Un control con agua o vino neutro ayuda a separar efecto de la copa y efecto del vino para esa botella y temperatura de servicio.'
    ]
  },
  'aroma-language': additions['aroma-language-detail'],
  'vine-year': additions['vine-year-detail'],
  'terroir-layers': additions['terroir-layers-detail'],
  'maturation-vessels': additions['maturation-vessels-detail'],
  'lees-and-malolactic': {
    en: [
      'Lees are not a switch that is either on or off. Their volume, age, composition and distribution change after settling, racking and each stirring interval. A short, gentle bâtonnage can resuspend fine cells and release mannoproteins; frequent movement can increase oxygen exposure, disturb gross solids or hide a developing sulfur note. Sample from the same depth and keep a quiet portion when testing the effect. Describe whether the wine gained mid-palate breadth, chalky suspension, bitterness or merely temporary weight, because those observations point to different lees populations and handling choices.',
      'Malolactic monitoring needs an endpoint and a hygiene plan. Measure malic acid until it is stable, check pH and volatile acidity, and protect the wine with an appropriate sulfur strategy after the bacteria finish. Co-inoculation can shorten the interval between alcoholic and malolactic fermentation, while sequential inoculation gives the winemaker a clearer pause for settling and adjustment. Neither route guarantees a buttery profile: diacetyl, temperature, oxygen and bacterial strain interact. A matched pre- and post-MLF tasting, with the same temperature and glass, separates the acid conversion from the texture supplied by lees. Record the time between the last stirring and the sample, since suspended solids can distort the first impression.'
    ],
    de: [
      'Hefetrub ist kein Schalter, der einfach an oder aus ist. Menge, Alter, Zusammensetzung und Verteilung ändern sich nach Absetzen, Abstich und jedem Aufrührintervall. Kurzes, behutsames Bâtonnage kann feine Zellen aufwirbeln und Mannoproteine freisetzen; häufige Bewegung erhöht Sauerstoffkontakt, stört grobe Feststoffe oder verdeckt einen Schwefelton. Entnimm Proben stets aus gleicher Tiefe und behalte eine ruhige Teilmenge als Kontrolle. Beschreibe, ob der Wein mittlere Breite, kreidige Schwebung, Bitterkeit oder nur vorübergehendes Gewicht gewann; daraus lassen sich Trub und Führung besser ableiten.',
      'Malo-Kontrolle braucht ein Ende und einen Hygieneplan. Miss Apfelsäure bis zur Stabilität, prüfe pH und flüchtige Säure und schütze den Wein nach Abschluss mit einer passenden Schwefelführung. Co-Inokulation kann die Zeit zwischen alkoholischer und malolaktischer Gärung verkürzen; sequenzielle Beimpfung lässt mehr Raum für Absetzen und Anpassung. Keine Methode garantiert Butter: Diacetyl, Temperatur, Sauerstoff und Bakterienstamm wirken zusammen. Ein Vergleich vor und nach Malo bei gleichem Glas und gleicher Temperatur trennt Säureumwandlung von Hefetextur. Notiere auch den Abstand zwischen letztem Aufrühren und Probe, weil Schwebestoffe den ersten Eindruck und die Stabilität verschieben.'
    ],
    fr: [
      'Les lies ne sont pas un interrupteur. Leur volume, leur âge, leur composition et leur répartition changent après dépôt, soutirage et chaque bâtonnage. Un mouvement bref et doux remet les cellules fines en suspension et libère des mannoprotéines ; des gestes fréquents augmentent l’oxygène, déplacent les solides grossiers ou masquent une note soufrée. Prélevez à la même profondeur et gardez une fraction immobile comme témoin. Décrivez ampleur médiane, suspension crayeuse, amertume ou simple poids temporaire : ces observations orientent vers des lies et des conduites différentes.',
      'Le suivi de la malo demande une fin mesurée et une hygiène planifiée. Mesurez l’acide malique jusqu’à stabilité, contrôlez pH et volatile, puis protégez le vin avec une gestion du soufre adaptée. La co-inoculation raccourcit parfois l’intervalle entre fermentations ; l’inoculation séquentielle laisse une pause plus lisible pour débourber et ajuster. Aucune voie ne garantit le beurre : diacétyle, température, oxygène et souche interagissent. Une dégustation avant et après malo, à température et verre identiques, sépare conversion acide et texture de lies. Notez l’intervalle entre bâtonnage et prélèvement, car les solides en suspension changent la première sensation.'
    ],
    es: [
      'Las lías no son un interruptor de encendido y apagado. Su volumen, edad, composición y distribución cambian después de asentarse, trasegar y remover. Un bâtonnage breve y suave resuspende células finas y libera manoproteínas; mover a menudo aumenta oxígeno, desplaza sólidos gruesos o esconde un tono sulfuroso. Toma muestras a la misma profundidad y conserva una parte quieta como control. Describe si ganó amplitud media, suspensión calcárea, amargor o solo peso temporal: cada observación apunta a una población de lías y manejo distintos.',
      'El seguimiento de la maloláctica necesita un final medido y un plan de higiene. Mide ácido málico hasta que se estabilice, comprueba pH y acidez volátil y protege el vino con una estrategia de azufre adecuada al terminar. La coinoculación puede acortar el intervalo entre fermentaciones; la inoculación secuencial deja una pausa más clara para asentar y ajustar. Ninguna ruta garantiza mantequilla: diacetilo, temperatura, oxígeno y cepa bacteriana interactúan. Una cata antes y después de la maloláctica, con igual copa y temperatura, separa conversión ácida y textura de lías. Anota el tiempo entre removido y muestra, porque los sólidos suspendidos alteran la primera sensación en el vaso servido claramente.'
    ]
  },
}

const deExtras: Record<string, string> = {
  'vine-to-glass': 'Auch Pressdruck, Trubmenge und Kopfraum verdienen einen eigenen Eintrag. Ein sauberer Vergleich hält diese Größen fest, sonst erscheint ein Unterschied im Glas wie eine Wirkung des Gefäßes, obwohl vielleicht nur die Partie oder die Sauerstoffführung wechselte. Das Protokoll macht spätere Flaschen lernfähig.',
  'taste-with-intention': 'Bei deutscher Verkostungssprache lohnt es sich, Mundgefühl und Urteil zu trennen. „Trocken“ kann Süße meinen, „herb“ Bitterkeit oder Gerbstoff. Schreibe die konkrete Empfindung zuerst und verwende das vertraute Wort erst danach, damit alle am Tisch dieselbe Beobachtung prüfen können.',
  'sparkling-methods': 'Die zweite Gärung erzeugt nicht automatisch lange Flaschenreife. Erst Hefekontakt, Temperatur, Dauer und spätere Dosage erklären, ob Mousse cremig, straff oder schnell zerfallend wirkt. Auch die Glasform verändert die sichtbare Perlage, weshalb der Vergleich mit identischen Gläsern beginnt. Bei einer Verkostung sollte außerdem der Druckverlust durch langes Stehen und die Schaumbildung beim Einschenken notiert werden; sonst wird ein Serviceeffekt fälschlich der Methode zugeschrieben. Der Grundwein bleibt die Säureachse, an der sich Dosage und Autolyse messen lassen.',
  'red-white-rose': 'Bei Rosé sollte auch der Zeitpunkt des Pressens genannt werden. Saft aus der frühen Pressfraktion kann eine andere Säure und Phenollast besitzen als späterer Saft. So wird verständlich, warum zwei helle Weine trotz ähnlicher Farbe unterschiedlich griffig oder salzig wirken.',
  'sweet-wine': 'Die Analyse von Süßwein beginnt deshalb mit kleinen Schlucken. Nach dem ersten Eindruck folgt die Frage, ob Säure den Zucker trägt, ob Alkohol Wärme bringt und ob Bitterkeit den Abgang verlängert. Erst diese Beziehungen zeigen, ob Konzentration ausgewogen oder bloß schwer wirkt. Bei Botrytiswein zählt außerdem, ob die honigartige Aromatik von frischer Säure und sauberem Abgang getragen wird oder in sirupartige Breite kippt; dieselbe Restzuckermenge kann je nach pH ganz anders wirken.',
  'fortified-wine': 'Bei verstärktem Wein sollte die Altersangabe vorsichtig gelesen werden. Solera, Verschnitt und Verdunstung machen den Inhalt zu einer zeitlichen Mischung. Ein Glas beweist nicht allein den Ausbauweg; Etikett, Fassgeschichte und die Abfolge von Süße, Säure und Wärme liefern gemeinsam die bessere Erklärung. Notiere beim Vergleich auch die Alkoholwärme am Gaumen und die Zeit bis zum Rückgang: ein florbetonter, trockener Wein kann trotz hoher Stärke schlank wirken, während ein süßer Wein die Wärme durch Extrakt nur scheinbar verdeckt. Farbe, Oxidationsnote und Salzempfinden ergänzen diese zeitliche Lesart.',
  service: 'Praktisch bedeutet das: erst eine kleine Probe verändern und dann entscheiden. Ein kaltes Glas, ein sauberer Ausschank und zehn Minuten Zeit können mehr zeigen als ein großes Dekantiergefäß. So bleibt Service reversibel, und die Flasche wird nicht durch eine vorschnelle Behandlung verbraucht. Bei einer alten Flasche kommen Füllstand, Korkzustand und Depot hinzu; diese Hinweise bestimmen, ob langsames Ausschenken wichtiger ist als zusätzliche Luft. Bei Schaumwein zählt zudem der Druckverlust nach dem Öffnen.',
  'glassware-anatomy': 'Auch das Halten am Kelchrand oder der Handwärme kann die Probe verändern. Wer den Vergleich ernst nimmt, fasst den Stiel, misst die Menge und prüft beide Gläser in wechselnder Reihenfolge. Das Ergebnis beschreibt den konkreten Wein, nicht eine allgemeine Rangordnung der Formen. Eine breite Schale kann zudem Schwefel oder flüchtige Säure deutlicher machen; deshalb sollte derselbe Wein zuerst ohne Schwenken und danach mit identischer Bewegung geprüft werden. Füllmenge und Raumtemperatur gehören ins Protokoll.',
  'aroma-language': 'Eine gute deutsche Notiz darf Unsicherheit sichtbar lassen. „Zitrus, vielleicht Grapefruit“ ist stärker als eine erfundene Präzision, wenn die Referenz nicht sicher ist. Nach einigen Minuten kann die Wahrnehmung erneut geprüft und als Entwicklung, nicht als völlig neuer Duft, notiert werden. Für die Schulung hilft ein Dreischritt aus Familie, konkreter Referenz und Sicherheit: „rote Frucht, Sauerkirsche, mittel sicher“ ist nachvollziehbarer als eine lange Liste selten genannter Früchte. So bleibt die Sprache zwischen Personen vergleichbar.',
  'vine-year': 'Für die Ernteentscheidung zählen außerdem Botrytisrisiko, Arbeitskapazität und Logistik. Ein Betrieb kann physiologische Reife abwarten, aber Regen oder verfügbare Hände begrenzen die Wahl. Der Jahrgang erzählt daher nicht nur vom Himmel, sondern auch davon, welche Kompromisse praktisch möglich waren.',
  'terroir-layers': 'Ein Profil kann in wenigen Metern wechseln. Steine an der Oberfläche zeigen weder Wasserspeicher noch Wurzeltiefe; dafür braucht es Gruben, Bohrungen, Wetterdaten und Beobachtung der Rebe. Herkunft wird glaubwürdig, wenn solche Ebenen zusammen gelesen werden und kein einzelner Bodenname alles erklären soll. Auch die Unterlage und die Bewirtschaftung gehören in den Vergleich: gleiche Sorte auf zwei Unterlagen oder mit unterschiedlicher Begrünung kann den Wasserstress stärker verändern als der Gesteinsname auf dem Etikett. Hangwind und nächtliche Abkühlung sollten ebenso protokolliert werden wie die Bodenprobe, die Laubwand und der Erntetermin. Erst die Wiederholung über mehrere Parzellen macht daraus mehr als eine Einzelfallgeschichte.',
  fermentation: 'Dichte allein genügt nicht, weil sie Temperatur und gelöstes Kohlendioxid widerspiegeln kann. Geruch, Probeschluck und Verlauf zeigen, ob die Hefe gesund arbeitet. Ein Eingriff sollte dokumentiert und möglichst mit einer unbehandelten Probe verglichen werden, damit seine Wirkung nicht nur vermutet wird.',
  'maturation-vessels': 'Auch ein neutrales Gefäß ist nicht ereignislos. Bewegung der Hefe, Temperaturgradient, Füllstand und Schwefelmanagement beeinflussen die Entwicklung. Wer Holz, Beton oder Stahl vergleicht, sollte daher Pflege und Zeitpunkt gleich halten; sonst werden mehrere Ursachen zu einer scheinbaren Materialwirkung vermischt.',
  'lees-and-malolactic': 'Die Begriffe „weich“ und „cremig“ brauchen eine genauere Beschreibung. Hefelager kann Volumen und Schwebestoffe geben, Malo die Säurespitze senken, Holz Wärme hinzufügen. Säureprofil, Tannin und Abgang zeigen, welcher Eindruck tatsächlich verändert wurde und ob die Frische erhalten blieb. Eine sensorische Kontrolle schützt vor Kurzschlüssen. Bei Weißwein ist außerdem zu prüfen, ob Aufrühren den Trub gleichmäßig verteilt oder nur kurzfristig den Eindruck von Dichte erzeugt; eine Probe nach dem Absetzen trennt diesen Effekt von echter Textur. Erst die Gegenprobe mit gleicher Schwefel- und Temperaturgeschichte zeigt, ob der Eindruck stabil bleibt.',
}

export const guideDepthA: GuideDepthRecord = Object.fromEntries(
  Object.entries(baseByGuide).map(([id, locales]) => [
    id,
    Object.fromEntries((['en', 'de', 'fr', 'es'] as GuideDepthLocale[]).map(locale => [
      locale,
      [...(locales[locale] ?? []), ...(additions[id]?.[locale] ?? []), ...(specificExtras[id]?.[locale] ?? []), ...(topUps[id]?.[locale] ?? []), ...(locale === 'de' && deExtras[id] ? [deExtras[id]] : []), ...(id === 'aroma-language' && locale === 'en' ? ['Keep the reference ordinary, observable and open to revision after another smell.'] : [])],
    ])),
  ]),
) as GuideDepthRecord

